import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"58、【兌】 兌下兌上","description":"子夏易傳 - 58、【兌】 兌下兌上","frontmatter":{"title":"58、【兌】 兌下兌上","description":"子夏易傳 - 58、【兌】 兌下兌上"},"headers":[],"relativePath":"classics/zixia/060.md","filePath":"classics/zixia/060.md"}'),i={name:"classics/zixia/060.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_58、【兌】-兌下兌上" tabindex="-1">58、【兌】 兌下兌上 <a class="header-anchor" href="#_58、【兌】-兌下兌上" aria-label="Permalink to “58、【兌】 兌下兌上”">​</a></h1><p>卦辭：兌，亨利貞。</p><p>彖曰：兌，說也。剛中而柔外，說以利貞，是以順乎天而應乎人。說以先民，民忘其勞。說以犯難，民忘其死。說之大民勸矣哉。</p><p>子夏：剛中正而外柔，順於萬物，皆說其澤。聖人以說先人，而民忘其勞，以說犯難，民則忘死。非大人不能說於民，而民鹹說而得其正也。</p><p>象曰：麗澤，兌。君子以朋友講習。</p><p>子夏：兩說而合，者莫過於朋友講習也。</p><p>初九，和兌吉。</p><p>象曰：和兌之吉，行未疑也。</p><p>子夏：以剛正之說，首出門而和人也。守正和人也。守正和人，何往不吉。行豈疑哉。</p><p>九二，孚兌吉。悔亡。</p><p>象曰：孚兌之吉，信志也。</p><p>子夏：失位與三，豈無悔也。志在和人，欲其說，信中不失正，故吉也。夫何悔焉。</p><p>六三，來兌兇。</p><p>象曰：來兌之兇，位不當也。</p><p>子夏：兌者，陽說隂也。過說於上，柔以來人，使人從欲者也。何以終哉，兇其宜也。</p><p>九四，商兌未寧，介疾有喜。</p><p>象曰：九四之喜，有慶也。</p><p>子夏：幹居臣位，商量冝制，祗上使下，不敢自安，皆獲所說，必得其慶也。故大速有喜也。</p><p>九五，孚於剝，有厲。</p><p>象曰：孚於剝位，正當也。</p><p>子夏：隂二君而一民，小人之道也。處尊而孚於上，隂信於小人消君子之道也。得位正當為人之刑，則下化矣。下之消則上危也。可不慎乎。</p><p>上六。引兌。</p><p>象曰：上六引兌，未光也。</p><p>子夏：為五牽說，信而尚之，柔而匪正也。雖說來矣，豈足光哉。</p>',24)])])}const f=a(i,[["render",r]]);export{m as __pageData,f as default};
